package io.github.hoangtnedu.java.warehouse;
import io.github.hoangtnedu.java.orders.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;
public class App {public static void main(String[] args)throws Exception{Database.init();SwingUtilities.invokeLater(()->{JTextField username=new JTextField("warehouse",10);JPasswordField password=new JPasswordField(12);JPanel login=new JPanel();login.add(username);login.add(password);if(JOptionPane.showConfirmDialog(null,login,"Warehouse login",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{Database.User user=Database.authenticate(username.getText(),new String(password.getPassword()));if(user==null||!"WAREHOUSE".equals(user.role()))throw new IllegalArgumentException("Wrong user/role");JFrame f=new JFrame("HoangTN Warehouse");DefaultTableModel model=new DefaultTableModel(new Object[]{"Order","Status","Version"},0);JTable table=new JTable(model);WarehouseService service=new WarehouseService();JPanel buttons=new JPanel();for(String action:new String[]{"Refresh","PROCESSING","READY"}){JButton b=new JButton(action);buttons.add(b);b.addActionListener(e->{b.setEnabled(false);long id=table.getSelectedRow()<0?-1:((Number)model.getValueAt(table.getSelectedRow(),0)).longValue();new SwingWorker<java.util.List<Object[]>,Void>(){protected java.util.List<Object[]> doInBackground()throws Exception{if(!action.equals("Refresh"))service.move(user,id,action);return service.pending();}protected void done(){try{model.setRowCount(0);get().forEach(model::addRow);}catch(Exception ex){JOptionPane.showMessageDialog(f,ex.getMessage());}finally{b.setEnabled(true);}}}.execute();});}f.add(new JScrollPane(table));f.add(buttons,BorderLayout.SOUTH);f.setSize(700,450);f.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);f.setVisible(true);}catch(Exception ex){JOptionPane.showMessageDialog(null,ex.getMessage());}});}}